                        style="
                            width:73%;

                            margin:5px auto 0 auto;

                            border-collapse:separate;

                            border-spacing:4px 0;

                            table-layout:fixed;

                            direction:ltr;
                        "
                    >

                        <tr>


                            <!-- =============================
                                 USD AMOUNT
                            ============================== -->

                            <td
                                style="
                                    width:36%;
                                    height:40px;

                                    border:1.5px solid #222;

                                    text-align:center;
                                    vertical-align:middle;

                                    font-family:Arial,sans-serif !important;

                                    font-size:18px;
                                    font-weight:700;
                                "
                            >

                                {% if doc.currency == "USD" %}

                                    {{ "{:,.2f}".format(
                                        doc.donation_amount or 0
                                    ) }}

                                {% endif %}

                            </td>



                            <!-- USD SYMBOL -->

                            <td
                                style="
                                    width:12%;
                                    height:40px;

                                    border:1.5px solid #222;

                                    text-align:center;
                                    vertical-align:middle;

                                    font-family:Arial,sans-serif !important;

                                    font-size:20px;
                                    font-weight:700;
                                "
                            >

                                $

                            </td>



                            <!-- =============================
                                 LBP AMOUNT
                            ============================== -->

                            <td
                                style="
                                    width:36%;
                                    height:40px;

                                    border:1.5px solid #222;

                                    text-align:center;
                                    vertical-align:middle;

                                    font-family:Arial,sans-serif !important;

                                    font-size:18px;
                                    font-weight:700;
                                "
                            >

                                {% if doc.currency == "LBP" %}

                                    {{ "{:,.0f}".format(
                                        doc.donation_amount or 0
                                    ) }}

                                {% endif %}

                            </td>



                            <!-- LBP SYMBOL -->

                            <td
                                style="
                                    width:12%;
                                    height:40px;

                                    border:1.5px solid #222;

                                    text-align:center;
                                    vertical-align:middle;

                                    direction:rtl;

                                    font-size:18px;
                                    font-weight:700;
                                "
                            >

                                ل.ل.

                            </td>


                        </tr>

                    </table>


                </td>


            </tr>

        </table>



        <!-- =================================================
             DONOR NAME + PHONE
        ================================================== -->

        <table

            dir="rtl"

            style="
                width:100%;

                direction:rtl;

                border-collapse:collapse;

                table-layout:fixed;

                margin-top:5px;

                margin-bottom:6px;
            "
        >

            <tr>


                <!-- =========================================
                     DONOR
                ========================================== -->

                <td
                    style="
                        width:60%;

                        text-align:right;

                        vertical-align:bottom;

                        padding-left:10px;
                    "
                >


                    <span class="form-label">

                        وصلنا من:

                    </span>


                    <span

                        class="dotted-value"

                        style="
                            width:68%;
                            text-align:center;
                        "
                    >

                        {{ doc.donor_name or doc.donor or "" }}

