                            <td

                                rowspan="2"

                                class="date-label"

                                style="
                                    width:29%;

                                    text-align:right;

                                    vertical-align:top;

                                    padding-top:1px;
                                "
                            >

                                التاريخ:

                            </td>



                            <td

                                dir="ltr"

                                class="date-value"

                                style="
                                    width:56%;

                                    direction:ltr;

                                    text-align:center;
                                "
                            >


                                {% if hijri_date %}

                                    {{ hijri_year }}
                                    /
                                    {{ hijri_month }}
                                    /
                                    {{ hijri_day }}

                                {% else %}

                                    &nbsp;&nbsp;&nbsp;&nbsp;
                                    /
                                    &nbsp;&nbsp;&nbsp;
                                    /
                                    &nbsp;&nbsp;&nbsp;

                                {% endif %}


                            </td>



                            <td
                                style="
                                    width:15%;

                                    text-align:center;

                                    font-size:19px;

                                    font-weight:700;
                                "
                            >

                                هـ

                            </td>


                        </tr>



                        <!-- ================================
                             GREGORIAN DATE
                        ================================= -->

                        <tr>


                            <td

                                dir="ltr"

                                class="date-value"

                                style="
                                    direction:ltr;

                                    text-align:center;
                                "
                            >


                                {% if doc.posting_date %}

                                    {{ gregorian_year }}
                                    /
                                    {{ gregorian_month }}
                                    /
                                    {{ gregorian_day }}

                                {% else %}

                                    &nbsp;&nbsp;&nbsp;&nbsp;
                                    /
                                    &nbsp;&nbsp;&nbsp;
                                    /
                                    &nbsp;&nbsp;&nbsp;

                                {% endif %}


                            </td>



                            <td
                                style="
                                    text-align:center;

                                    font-size:19px;

                                    font-weight:700;
                                "
                            >

                                م

                            </td>


                        </tr>


                    </table>


                </td>



                <!-- =========================================
                     TREASURER
                ========================================== -->

                <td
                    style="
                        width:30%;

                        text-align:center;

                        vertical-align:top;

                        padding:0 2px;
                    "
                >


                    <div class="bottom-title">
    أمين الصندوق
</div>

<div class="bottom-name">
    ماجدة تذكرجي
</div>

<div style="
    margin-top: 2px;
    text-align: center;
    height: 45px;
">
    <img
        src="https://i.imgur.com/t8U9lax.png"
        alt="توقيع أمين الصندوق"
        style="
            max-width: 115px;
            max-height: 43px;
            width: auto;
            height: auto;
            object-fit: contain;
        "
    >
</div>


                </td>



                <!-- =========================================
                     RECEIVER
                ========================================== -->

                <td
                    style="
                        width:30%;

                        text-align:center;

                        vertical-align:top;

                        padding:0 2px;
                    "
                >


                    <div class="bottom-title">

                        المستلم

                    </div>


                    <div
                        class="bottom-name"

                        style="
                            font-family:Arial,sans-serif !important;
                            font-size:16px;
                            font-weight:700;
                        "
                    >

                        {{ user.full_name or "" }}

                    </div>


                </td>


            </tr>

        </table>



        <!-- =================================================
             FOOTER
        ================================================== -->

        <div
            style="
                width:100%;

                margin-top:15px;

                border:1.5px solid #333;

                min-height:28px;

                padding:4px 6px;

                box-sizing:border-box;

                font-size:11px;

                font-weight:500;

                line-height:1.4;

                text-align:center;

                direction:rtl;

                white-space:nowrap;
            "
        >


            هاتف:

            بيروت:

            <span
                dir="ltr"
                style="font-family:Arial,sans-serif !important;"
            >
                01/644660 - 01/651990
            </span>


            &nbsp; - &nbsp;


            طرابلس:

            <span
                dir="ltr"
                style="font-family:Arial,sans-serif !important;"
            >
                06/442638
            </span>


            &nbsp; - &nbsp;


            البقاع:

            <span
                dir="ltr"
                style="font-family:Arial,sans-serif !important;"
            >
                03/819357
            </span>


            &nbsp; - &nbsp;


            صيدا:

            <span
                dir="ltr"
                style="font-family:Arial,sans-serif !important;"
            >
                07/735074
            </span>


            &nbsp; - &nbsp;


            <span
                dir="ltr"
                style="font-family:Arial,sans-serif !important;"
            >

                E-mail: itihad@itihad.org

            </span>


        </div>


    </div>

</div>

